 manifest=read(s/'source_manifest.json');reuse=dict(native='native',single_neural='single_neural',rewriter='rewriter',benign_retrieval='boundary',benign_random='random_boundary')
 p=dict(schema='channel_retrieval_v1',frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),parent=str(parent),runtime_root=str(rt),runtime_commit=old['runtime_commit'],source_commit=manifest['source_commit'],sources=manifest['files'],inputs=inputs,datasets=old['datasets'],reuse=reuse,arms=list(reuse)+['channel','random_channel','random_joint','uniform','random_uniform'],TEST_allowed=False,settings=dict(regions=3,horizon=2,shortlist_per_channel_region=8,temperature=1,stop_gain=1e-5,sequence_tolerance=1e-5,logit_tolerance=2e-5),resources=dict(CPU_threads=4,nice=10,GPU_hours=0,API_calls=0,preflight_seconds=1800,selection_seconds=14400,evaluation_seconds=3600,audit_seconds=900,automatic_retry=False),caps=dict(physical_builds=6000,teacher_contexts=48000,backward_calls=800,official_GAGA_VALID=1920),primary_candidate='channel',primary='Channel candidate must beat native, existing single neural, existing rewriter, previous benign retrieval, same-channel random and joint-pool random by pooled MR in BOTH datasets. Report uniform-shortlist contrast and all repeat outcomes. No outcome-selected case exclusions.',limitations=['This is adaptive development after a null YelpChi result, on reused cohorts; not untouched confirmation.','All target membership/order/features and injected features/physical degrees/budgets remain fixed. Known TRAIN labels may guide endpoint eligibility; no VALID/TEST endpoint labels or victim feedback select actions.','The endpoint pool expands from TRAIN-benign to TRAIN-benign plus TRAIN-fraud. This changes the downstream candidate setting and must be reported, although the original attack already knows TRAIN labels.','GAGA has label-grouped relation tokens. Type-aware search borrows the general typed-message idea of HGT and discrete derivative ranking of HotFlip; neither is claimed as a new theorem, HGT implementation or first novelty.','Same-class random conditions on selected donor slots and endpoint classes, isolating within-class endpoint choice. Joint random samples the full legal union, matching slots/dose but not class frequencies. Uniform shortlist searches both classes with the same per-step verification width, without derivative ranking.','Search has twice the per-region shortlist opportunities of the prior benign-only study. Same physical budget is not equal computation. Uniform search controls the new per-step verification count; STOP may change total work.','Both datasets seal before either new official scoring. Fixed TRAIN parity covers both classes and mixed two-substitution combinations; all final new/random graphs are physically checked.','One fixed author upstream and own teacher per dataset, three correlated capture repetitions. No new upstream/teacher training/API/GPU/TEST. Root authorship is not independent or human review.'])
